const aplatir = (v, acc = []) => { if (typeof v === 'string' || typeof v === 'number') acc.push(String(v)); else if (v && typeof v === 'object') for (const x of Object.values(v)) aplatir(x, acc); return acc; };
const naif = (iso) => { const d = new Date(iso); return Number.isNaN(d.getTime()) ? null : d.toLocaleString('sv-SE', { timeZone: 'Europe/Paris' }).replace(' ', 'T'); };
const minutes = (n) => Date.parse(n + 'Z') / 60000;
const jourDe = (n) => String(n).slice(0, 10);
const ajouterJours = (j, k) => new Date(Date.parse(j + 'T00:00:00Z') + k * 86400000).toISOString().slice(0, 10);
const joursEntre = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const aujourdhui = jourDe(naif(new Date().toISOString()));
const eur = (c) => (Number.isInteger(c) ? (c / 100).toFixed(2).replace('.', ',') : null);
const org = $('Réglages de la copie').first().json.organisation_id;
const mien = (r) => !!r && r.organisation_id === org;
const config = $('Lire la configuration').all().map((i) => i.json).find(mien) ?? {};
const annexe = {};
for (const r of $('Lire l’annexe d’autonomie').all()) if (mien(r.json) && r.json.type_action) annexe[r.json.type_action] = r.json;
const faits = {};
for (const r of $('Lire les actions du jour').all()) if (mien(r.json) && r.json.type_action && r.json.statut === 'faite' && r.json.effet !== 'carte') faits[r.json.type_action] = (faits[r.json.type_action] || 0) + 1;
const DEFAUTS = {"repondre_avis_negatif":1,"prevenir_equipe":3};
const niveau = (t) => Math.min(3, Math.max(1, Number(annexe[t]?.niveau ?? DEFAUTS[t] ?? 2)));
const delai = Math.max(0, Math.floor(Number(config.delai_annulation_min ?? 10)));
const INTERNES = ['deposer_conversation', 'prevenir_equipe', 'indicateur_ads', 'note_interet', 'validation_equipe', 'marquer_evenement', 'indicateur_encaissements', 'compteur_ia', 'import_ligne'];
const JAMAIS_AUTO = ['demande_signature', 'planifier_chantier', 'solder_facture', 'facturer_chantier'];
const restes = {};
const modeDe = (t) => {
  const n = niveau(t);
  if (n === 1) return 'prepare';
  if (n === 2) return 'carte';
  if (INTERNES.includes(t)) return 'auto';
  if (restes[t] === undefined) restes[t] = Math.max(0, Number(annexe[t]?.plafond_jour ?? 20) - (faits[t] || 0));
  if (restes[t] <= 0) return 'carte';
  restes[t] -= 1;
  return 'auto';
};
const entreprise = coupe(config.raison_affichee, 70);
const plan = [];
const poser = (lane, type, base, donnees, forcerCarte) => {
  const m0 = modeDe(type);
  const forcer = !!forcerCarte || JAMAIS_AUTO.includes(type);
  const m = forcer && m0 === 'auto' ? 'carte' : m0;
  if (forcer && m0 === 'auto' && restes[type] !== undefined) restes[type] += 1;
  const effet = { effet: lane, type_action: type, organisation_id: org, entreprise, cle_idempotence: base + ':' + type, ...donnees };
  const perim = config.perimetres?.[type] ?? 'direction';
  if (m === 'auto' && delai > 0 && !INTERNES.includes(type)) plan.push({ json: { effet: 'carte', type_action: type, mode: 'auto_differe', statut_carte: 'annulable', pour_effet: lane, organisation_id: org, entreprise, cle_idempotence: base + ':' + type + ':carte', perimetre: coupe(perim, 40), approbateurs_roles: [], canal_equipe: '', execute_apres: new Date(Date.now() + delai * 60000).toISOString(), resume: coupe(donnees.resume, 300), charge: { ...effet, mode: 'auto' } } });
  else if (m === 'auto') plan.push({ json: { ...effet, mode: 'auto' } });
  else plan.push({ json: { effet: 'carte', type_action: type, mode: m, statut_carte: m === 'prepare' ? 'brouillon' : 'a_valider', pour_effet: lane, organisation_id: org, entreprise,
    cle_idempotence: base + ':' + type + ':carte', perimetre: coupe(config.perimetres?.[type] ?? 'direction', 40), approbateurs_roles: Array.isArray(config.approbateurs?.[config.perimetres?.[type] ?? 'direction']) ? config.approbateurs[config.perimetres?.[type] ?? 'direction'] : ['gerant'], canal_equipe: coupe(config.canaux_validation?.[config.perimetres?.[type] ?? 'direction'], 80), resume: coupe(donnees.resume, 300), charge: { ...effet, mode: 'auto' } } });
};
const info = (base, type, resume) => {
  const p = coupe(config.perimetres?.[type] ?? 'direction', 40);
  plan.push({ json: { effet: 'carte', type_action: type, mode: 'information', statut_carte: 'information', pour_effet: 'aucun', organisation_id: org, entreprise, cle_idempotence: base + ':' + type + ':info:carte', perimetre: p,
    approbateurs_roles: Array.isArray(config.approbateurs?.[p]) ? config.approbateurs[p] : ['gerant'], canal_equipe: coupe(config.canaux_validation?.[p], 80), resume: coupe(resume, 300), charge: { effet: 'aucun' } } });
};
const retours = $('Qualifier les retours').all().map((i) => i.json);
const rev = new Map(($('Revalider le rédacteur').isExecuted ? $('Revalider le rédacteur').all() : []).map((i) => [i.json.cle_idempotence, i.json]));
const boite = config.boite_client === 'outlook' ? 'outlook' : 'gmail';
const LANES = { google: 'repondre_google', trustpilot: 'reponse_plateforme', chatwoot: 'reponse_plateforme', zendesk: 'repondre_zendesk' };
const gravite = { positif: 0, neutre: 1, negatif: 2, tres_mecontent: 3 };
const alertes = [];
for (const e of retours) {
  const base = e.cle_idempotence;
  if (e.genre === 'ticket' && e.canal === 'chatwoot') poser('marquer_evenement', 'marquer_evenement', base, { ref: e.ref, resume: 'Événement de la plateforme lu' });
  if (e.genre === 'avis' || e.genre === 'ticket') {
    const r = rev.get(base);
    // Le sentiment retenu est le PIRE de celui du code (les étoiles) et de celui du modèle : le modèle ne peut qu'aggraver.
    const code = e.negatif_code ? 'negatif' : e.etoiles === 4 ? 'neutre' : 'positif';
    const sentiment = r && gravite[r.sentiment] > gravite[code] ? r.sentiment : code;
    const mecontent = gravite[sentiment] >= 2;
    if (mecontent) {
      // Un avis négatif ou un client mécontent va TOUJOURS à un humain : jamais de publication, même au niveau le plus autonome de l'annexe.
      if (r) poser(LANES[e.canal], 'repondre_avis_negatif', base, { avis_ref: e.ref, canal: e.canal, texte: r.reponse, resume: 'Brouillon de réponse à ' + (e.genre === 'avis' ? 'un avis à ' + e.etoiles + ' étoile(s)' : 'un client mécontent') + ' (' + e.canal + ')' }, true);
      alertes.push((e.genre === 'avis' ? 'Avis à ' + e.etoiles + ' étoile(s) sur ' + e.canal : 'Client mécontent sur ' + e.canal) + ' : à traiter par un humain.');
      if (!r) info(base, 'repondre_avis_negatif', 'À traiter par un humain (' + e.canal + ') : réponse non rédigée');
    } else if (r) poser(LANES[e.canal], e.genre === 'avis' ? 'repondre_avis' : 'repondre_ticket', base, { avis_ref: e.ref, canal: e.canal, texte: r.reponse, resume: 'Réponse préparée (' + e.canal + ')' });
  } else if (e.genre === 'contrat' && e.a_proposer) {
    if (!e.tiers_courriel) { info(base, 'proposer_entretien', 'Contrat sans destinataire connu, entretien non proposé : ' + e.libelle); continue; }
    poser('courriel_' + boite, 'proposer_entretien', base, { destinataire: e.tiers_courriel, objet_ref: e.objet_ref, type_objet: 'contrat', palier: 1, objet: 'Entretien : ' + e.libelle, texte: 'Bonjour,\n\nVotre entretien (' + e.libelle + ') est à prévoir autour du ' + e.prochaine_visite.split('-').reverse().join('/') + '. Répondez à ce message pour convenir d’un rendez-vous.', resume: 'Proposer l’entretien : ' + e.libelle });
  }
}
const attentes = plan.filter((p) => p.json.effet === 'carte' && p.json.statut_carte === 'a_valider').length;
if (['slack', 'teams'].includes(config.outil_equipe) && (attentes > 0 || alertes.length) && retours[0]?.cle_idempotence) poser('prevenir_' + config.outil_equipe, 'prevenir_equipe', 'lot:' + retours[0]?.cle_idempotence, { texte: (attentes ? attentes + ' action(s) attendent une validation dans la plateforme. ' : '') + alertes.join(' ; '), canal_equipe: coupe(config.canal_alertes, 80), resume: 'Prévenir l’équipe' });
return plan;

